<template>
  <AccountLayout bare>
    <main class="coa-page">
      <section v-if="mode === 'list'">
        <div class="coa-heading"><h1>Accounts List</h1><nav class="coa-breadcrumb"><span>Dashboard</span><b>›</b><span>Accounts</span><b>›</b><strong>Accounts List</strong></nav></div>
        <div class="coa-toolbar">
          <div class="coa-toolbar-actions"><button class="coa-btn primary" @click="newItem"><Icon name="plus"/> New</button><button class="coa-btn" :disabled="!selected" @click="selected && edit(selected)"><Icon name="edit"/> Edit</button><button class="coa-btn danger" :disabled="!selected" @click="removeSelected"><Icon name="trash"/> Delete</button><button class="coa-btn success" @click="exportCsv"><Icon name="file"/> Export Excel</button><button class="coa-btn" @click="printList"><Icon name="print"/> Print</button><button class="coa-btn" @click="load"><Icon name="refresh"/> Refresh</button></div>
          <div class="coa-search"><Icon name="search"/><input v-model="search" placeholder="Search accounts..."/><button aria-label="Filter"><Icon name="filter"/></button></div>
        </div>
        <section class="coa-table-card"><div class="coa-table-wrap"><table class="coa-table"><thead><tr><th>No.</th><th>Group</th><th>Sub</th><th>Name</th><th>Account No.</th><th>Status</th><th>Balance (USD)</th><th>View Details</th></tr></thead><tbody>
          <tr v-for="(account, index) in filtered" :key="account.id" :class="{ selected: selected?.id === account.id }" @click="selected = account"><td>{{ index + 1 }}</td><td>{{ accountGroup(account.account_sub_type) }}</td><td>{{ account.account_sub_type }}</td><td>{{ account.account_name }}</td><td>{{ account.account_number }}</td><td><span class="coa-status" :class="account.status_active ? 'active' : 'inactive'">{{ account.status_active ? 'Active' : 'Inactive' }}</span></td><td class="balance">{{ currencyValue(account.opening_balance) }}</td><td><button class="details-link" @click.stop="edit(account)">View Details <span>›</span></button></td></tr>
          <tr v-if="!filtered.length"><td colspan="8" class="empty">No accounts found.</td></tr></tbody></table></div><footer class="coa-table-footer"><span>Showing {{ filtered.length ? 1 : 0 }} to {{ filtered.length }} of {{ filtered.length }} entries</span><div><button disabled>Previous</button><button class="current">1</button><button disabled>Next</button></div></footer></section>
      </section>
      <section v-else>
        <header class="coa-form-heading"><div><h1>Chart of Accounts <span>›</span> <em>{{ editing ? 'Edit Account' : 'New Account' }}</em></h1><p>{{ editing ? 'Update the account details below.' : 'Create a new account by entering account details below.' }}</p></div><div class="form-head-actions"><button class="coa-btn" @click="backToList"><Icon name="back"/> Back to List</button><button class="coa-btn primary" @click="save"><Icon name="save"/> Save Account</button></div></header>
        <form class="coa-form-card" @submit.prevent="save"><div class="coa-form-main"><div class="coa-basic-fields"><FormField label="Account Number" required><input v-model.trim="form.account_number" required placeholder="Enter account number" /></FormField><FormField label="Account Name" required><input v-model.trim="form.account_name" required placeholder="Enter account name" /></FormField></div>
          <section class="subtype-section"><label class="field-label">Account Sub Type <i>*</i></label><div class="subtype-grid"><section v-for="group in accountGroups" :key="group.name" class="subtype-group"><h3>{{ group.name }}</h3><label v-for="item in group.items" :key="item.code" class="subtype-option"><input v-model="form.account_sub_type" type="radio" :value="item.name" required/><span>{{ item.code }}</span><b>{{ item.name }}</b></label></section></div></section>
          <section class="holders"><label class="field-label">Dedicated Account Holder <small>(Optional)</small></label><div class="holder-options"><label v-for="holder in holderOptions" :key="holder"><input v-model="form.dedicated_account_holders" type="checkbox" :value="holder"/><span>{{ holder }}</span></label></div></section><div class="required-note"><span>i</span> Fields marked with <i>*</i> are required.</div>
        </div><aside class="coa-form-side"><FormField label="Opening Balance"><input v-model.number="form.opening_balance" min="0" step="0.01" type="number" /></FormField><FormField label="Opening Balance Date"><input v-model="form.opening_balance_date" type="date" /></FormField><FormField label="Currency"><select v-model="form.currency_id"><option :value="null">Select currency</option><option v-for="currency in currencies" :key="currency.id" :value="currency.id">{{ currency.currency_code }} - {{ currency.currency_name }}</option></select></FormField><FormField label="Sales Tax" optional><select><option>Select sales tax (optional)</option></select></FormField><div class="field"><label>Status <i>*</i></label><div class="status-options"><label><input v-model="form.status_active" type="radio" :value="true"/> Active</label><label><input v-model="form.status_active" type="radio" :value="false"/> Inactive</label></div></div><FormField label="Description" optional><textarea v-model="form.description" maxlength="250" placeholder="Enter description..."></textarea><small class="counter">{{ (form.description || '').length }} / 250</small></FormField><FormField label="Notes" optional><textarea v-model="form.notes" maxlength="250" placeholder="Enter notes..."></textarea><small class="counter">{{ (form.notes || '').length }} / 250</small></FormField></aside></form>
        <footer class="coa-form-footer"><button class="coa-btn primary" type="button" @click="newItem"><Icon name="plus"/> New</button><button class="coa-btn" type="button" :disabled="!editing"><Icon name="edit"/> Edit</button><button class="coa-btn danger" type="button" :disabled="!editing" @click="removeSelected"><Icon name="trash"/> Delete</button><button class="coa-btn primary" type="button" @click="save"><Icon name="save"/> Save</button><button class="coa-btn" type="button" @click="printList"><Icon name="print"/> Print</button></footer>
      </section>
    </main>
  </AccountLayout>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import client from '../api/client'
import AccountLayout from '../components/AccountLayout.vue'
const Icon = { props: ['name'], template: `<svg viewBox="0 0 24 24" aria-hidden="true"><path v-if="name==='plus'" d="M12 5v14M5 12h14"/><path v-else-if="name==='edit'" d="m4 16.5-.7 4.2 4.2-.7L19 8.5 15.5 5 4 16.5ZM14.5 6l3.5 3.5"/><path v-else-if="name==='trash'" d="M5 7h14m-9-3h4m-7 3 1 13h8l1-13M10 11v5m4-5v5"/><path v-else-if="name==='search'" d="m20 20-4.2-4.2m2-5.3a7.3 7.3 0 1 1-14.6 0 7.3 7.3 0 0 1 14.6 0Z"/><path v-else-if="name==='filter'" d="M4 5h16l-6 7v5l-4 2v-7L4 5Z"/><path v-else-if="name==='refresh'" d="M20 11a8 8 0 1 0 1 4m-1-9v5h-5"/><path v-else-if="name==='print'" d="M6 9V3h12v6M6 17H3v-7h18v7h-3m-12-3h12v7H6v-7Z"/><path v-else-if="name==='save'" d="M5 3h12l3 3v15H5V3Zm3 0v6h8V3m-7 18v-7h6v7"/><path v-else-if="name==='back'" d="M20 12H5m6-6-6 6 6 6"/><path v-else d="M6 3h8l4 4v14H6V3Zm8 0v5h5M9 13h6m-6 4h6"/></svg>` }
const FormField = { props: { label: String, required: Boolean, optional: Boolean }, template: `<div class="field"><label>{{ label }} <i v-if="required">*</i><small v-if="optional">(Optional)</small></label><slot/></div>` }
const rows = ref([]), currencies = ref([]), search = ref(''), mode = ref('list'), form = ref({}), selected = ref(null), editing = ref(false)
const holderOptions = ['Customer', 'Seller / Vendor', 'Employee', 'Bank', 'Credit Card', 'Government']
const make = items => items.map(([code, name]) => ({ code, name }))
const accountGroups = [{ name: 'Assets', items: make([['1010','Bank Account'],['1020','Cash on Hand'],['1030','Accounts Receivable'],['1040','Inventory'],['1050','Prepaid Expenses'],['1060','Fixed Assets'],['1070','Accumulated Depreciation'],['1080','Other Current Assets'],['1090','Other Assets']]) },{ name: 'Liabilities', items: make([['2010','Accounts Payable'],['2020','Credit Card'],['2030','Sales Tax Payable'],['2040','Payroll Liabilities'],['2050','Loan Payable'],['2060','Line of Credit'],['2070','Other Current Liabilities'],['2080','Long-Term Liabilities']]) },{ name: 'Equity', items: make([['3010',"Owner's Equity"],['3020','Share Capital'],['3030','Retained Earnings'],['3040','Current Year Earnings'],['3050','Drawings'],['3060','Dividends']]) },{ name: 'Income', items: make([['4010','Sales Revenue'],['4020','Service Revenue'],['4030','Rental Income'],['4040','Interest Income'],['4050','Other Income']]) },{ name: 'Cost of Goods Sold (COGS)', items: make([['5010','Materials'],['5020','Direct Labor'],['5030','Subcontractors'],['5040','Equipment Rental'],['5050','Freight In'],['5060','Other Direct Costs']]) },{ name: 'Expense', items: make([['6010','Office Expense'],['6020','Utilities'],['6030','Rent'],['6040','Insurance'],['6050','Vehicle Expense'],['6060','Fuel'],['6070','Telephone & Internet'],['6080','Professional Fees'],['6100','Repairs & Maintenance'],['6110','Advertising & Marketing'],['6120','Travel'],['6130','Meals & Entertainment'],['6140','Payroll Expense'],['6150','Depreciation Expense'],['6160','Other Expenses']]) }]
const subTypeGroup = Object.fromEntries(accountGroups.flatMap(group => group.items.map(item => [item.name, group.name])))
const filtered = computed(() => { const term = search.value.toLowerCase().trim(); return !term ? rows.value : rows.value.filter(a => [a.account_number, a.account_name, a.account_sub_type].some(x => String(x || '').toLowerCase().includes(term))) })
const accountGroup = type => subTypeGroup[type] || 'Other'
const currencyValue = value => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(Number(value || 0))
const load = async () => { const [accounts, options] = await Promise.all([client.get('/chart-of-accounts'), client.get('/chart-of-accounts/options')]); rows.value = accounts.data.data || []; currencies.value = options.data.data.currencies || [] }
const cleanForm = () => ({ account_number: '', account_name: '', account_sub_type: '', opening_balance: 0, opening_balance_date: '', currency_id: null, status_active: true, notes: '', description: '', dedicated_account_holders: [] })
const newItem = () => { form.value = cleanForm(); editing.value = false; selected.value = null; mode.value = 'form' }
const edit = account => { selected.value = account; form.value = { ...cleanForm(), ...account, opening_balance_date: account.opening_balance_date?.slice(0, 10) || '', dedicated_account_holders: Array.isArray(account.dedicated_account_holders) ? account.dedicated_account_holders : [] }; editing.value = true; mode.value = 'form' }
const backToList = () => { mode.value = 'list'; selected.value = null }
const save = async () => { if (!form.value.account_number || !form.value.account_name || !form.value.account_sub_type) return; const response = editing.value ? await client.put(`/chart-of-accounts/${form.value.id}`, form.value) : await client.post('/chart-of-accounts', form.value); selected.value = response.data.data; await load(); backToList() }
const removeSelected = async () => { const account = editing.value ? form.value : selected.value; if (!account?.id || !window.confirm(`Delete ${account.account_name}?`)) return; await client.delete(`/chart-of-accounts/${account.id}`); await load(); backToList() }
const exportCsv = () => { const heading = ['Group','Sub','Name','Account No.','Status','Balance (USD)']; const values = filtered.value.map(a => [accountGroup(a.account_sub_type), a.account_sub_type, a.account_name, a.account_number, a.status_active ? 'Active' : 'Inactive', a.opening_balance || 0]); const csv = [heading, ...values].map(row => row.map(v => `"${String(v).replaceAll('"','""')}"`).join(',')).join('\n'); const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv' })); link.download = 'chart-of-accounts.csv'; link.click(); URL.revokeObjectURL(link.href) }
const printList = () => window.print()
onMounted(load)
</script>

